/* Lot 98: animation and transition longhands and their coordinated lists (generated by scripts/lot98_animgen.py; expectations from scripts/lot98_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssanim_t g_a[WF_CSSANIM_MAX];
static wf_csstrans_t g_tr[WF_CSSANIM_MAX];
static char g_t[160];

static int along(int k, const char *v) { memset(g_a, 0x5a, sizeof(g_a)); return wf_cssanim_long(k, v, g_a, WF_CSSANIM_MAX); }
static int tlong(int k, const char *v) { memset(g_tr, 0x5a, sizeof(g_tr)); return wf_csstrans_long(k, v, g_tr, WF_CSSANIM_MAX); }
static int acoord(const char *const *v, const unsigned char *sh) {
    memset(g_a, 0x5a, sizeof(g_a));
    return wf_cssanim_coord(v, sh, g_a, WF_CSSANIM_MAX);
}
static int tcoord(const char *const *v, const unsigned char *sh) {
    memset(g_tr, 0x5a, sizeof(g_tr));
    return wf_csstrans_coord(v, sh, g_tr, WF_CSSANIM_MAX);
}

static const char *ez(const wf_cssease_t *e) {
    static char b[64];
    snprintf(b, sizeof(b), "%d %d %d %d %d %d %d", e->kind, e->pos, e->n, e->x1, e->y1, e->x2, e->y2);
    return b;
}

/* field k of animation j as written by a longhand */
static const char *alongf(int k, int j) {
    const wf_cssanim_t *a = &g_a[j];
    switch (k) {
    case WF_CSSANIM_L_NAME: return a->name[0] ? a->name : "-";
    case WF_CSSANIM_L_TIMING: return ez(&a->ease);
    case WF_CSSANIM_L_DURATION: snprintf(g_t, sizeof(g_t), "%d", a->dur); break;
    case WF_CSSANIM_L_DELAY: snprintf(g_t, sizeof(g_t), "%d", a->delay); break;
    case WF_CSSANIM_L_COUNT: snprintf(g_t, sizeof(g_t), "%d", a->iters); break;
    case WF_CSSANIM_L_DIRECTION: snprintf(g_t, sizeof(g_t), "%d", a->dir); break;
    case WF_CSSANIM_L_FILL: snprintf(g_t, sizeof(g_t), "%d", a->fill); break;
    case WF_CSSANIM_L_PLAY: snprintf(g_t, sizeof(g_t), "%d", a->paused); break;
    default: snprintf(g_t, sizeof(g_t), "%d", a->comp); break;
    }
    return g_t;
}

static const char *tlongf(int k, int j) {
    const wf_csstrans_t *t = &g_tr[j];
    switch (k) {
    case WF_CSSTRANS_L_PROPERTY: return t->prop[0] ? t->prop : "-";
    case WF_CSSTRANS_L_TIMING: return ez(&t->ease);
    case WF_CSSTRANS_L_DURATION: snprintf(g_t, sizeof(g_t), "%d", t->dur); break;
    case WF_CSSTRANS_L_DELAY: snprintf(g_t, sizeof(g_t), "%d", t->delay); break;
    default: snprintf(g_t, sizeof(g_t), "%d", t->discrete); break;
    }
    return g_t;
}

static const char *afield(int k) {
    const wf_cssanim_t *a = &g_a[k];
    snprintf(g_t, sizeof(g_t), "%s %d %d %d %d %d %d %d %s", a->name[0] ? a->name : "-", a->dur, a->delay,
             a->iters, a->dir, a->fill, a->paused, a->comp, ez(&a->ease));
    return g_t;
}

static const char *tfield(int k) {
    const wf_csstrans_t *t = &g_tr[k];
    snprintf(g_t, sizeof(g_t), "%s %d %d %d %s", t->prop[0] ? t->prop : "-", t->dur, t->delay, t->discrete, ez(&t->ease));
    return g_t;
}

static void test_l98_longs_0(void) {
    TEST_ASSERT_EQUAL(-1, along(6, "2 3"));
    TEST_ASSERT_EQUAL(-1, tlong(4, "allow , normal , normal"));
    TEST_ASSERT_EQUAL(2, along(5, "reverse , normal"));
    TEST_ASSERT_EQUAL_STRING("1", alongf(5, 0));
    TEST_ASSERT_EQUAL_STRING("0", alongf(5, 1));
    TEST_ASSERT_EQUAL(-1, along(5, "normal, reverse, alternate-reverse, alternate, add replace"));
    TEST_ASSERT_EQUAL(1, along(6, "none"));
    TEST_ASSERT_EQUAL_STRING("0", alongf(6, 0));
    TEST_ASSERT_EQUAL(-1, tlong(2, "inherit"));
    TEST_ASSERT_EQUAL(1, along(5, "reverse"));
    TEST_ASSERT_EQUAL_STRING("1", alongf(5, 0));
    TEST_ASSERT_EQUAL(-1, along(2, "ease, linear, steps(5), steps(3, jump-both), cubic-bezier(0.73 , 2.6599 , 0.49 , 0.05)"));
}

